INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15948, 'Microdrama Emerges as Mainstream Entertainment Format in India, Report Finds', 'शेयरचैट और मोज की रिपोर्ट: माइक्रोड्रामा भारत में मुख्यधारा का मनोरंजन प्रारूप बनकर उभरा', 'A report by ShareChat and Moj, in collaboration with Kantar, has identified microdrama as a mainstream entertainment format in India. The study highlights the growing popularity and acceptance of this short-form video content. The findings indicate a significant shift in audience consumption habits towards easily digestible and engaging digital content. This trend suggests a maturing digital entertainment landscape in the country.', 'शेयरचैट और मोज की केंटार के सहयोग से जारी एक रिपोर्ट में माइक्रोड्रामा को भारत में एक मुख्यधारा के मनोरंजन प्रारूप के रूप में पहचाना गया है। अध्ययन इस छोटे प्रारूप वाले वीडियो सामग्री की बढ़ती लोकप्रियता और स्वीकृति पर प्रकाश डालता है। निष्कर्ष दर्शकों की उपभोग की आदतों में आसानी से पचने योग्य और आकर्षक डिजिटल सामग्री की ओर एक महत्वपूर्ण बदलाव का संकेत देते हैं। यह प्रवृत्ति देश में डिजिटल मनोरंजन परिदृश्य के परिपक्व होने का सुझाव देती है।', '["Microdrama has become a mainstream entertainment format in India.", "The finding is based on a report by ShareChat and Moj, in collaboration with Kantar.", "The report highlights the growing popularity of short-form video content.", "This indicates a shift in audience consumption towards easily digestible digital content."]'::jsonb, '["माइक्रोड्रामा भारत में एक मुख्यधारा का मनोरंजन प्रारूप बन गया है।", "यह निष्कर्ष केंटार के सहयोग से शेयरचैट और मोज की रिपोर्ट पर आधारित है।", "रिपोर्ट छोटे प्रारूप वाले वीडियो सामग्री की बढ़ती लोकप्रियता पर प्रकाश डालती है।", "यह आसानी से पचने योग्य डिजिटल सामग्री की ओर दर्शकों की उपभोग की आदतों में बदलाव का संकेत देता है।"]'::jsonb, 'Entertainment', 'India', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "ShareChat and Mojs Report in Collaboration with Kantar Finds Microdrama has Emerged as a Mainstream Entertainment Format in India"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/sharechat-and-mojs-report-in-collaboration-with-kantar-finds-microdrama-has-emerged-as-a-mainstream-entertainment-format-in-india/article71359860.ece", "headline": "ShareChat and Moj’s Report in Collaboration with Kantar Finds Microdrama has Emerged as a Mainstream Entertainment Format in India"}]'::jsonb, '{"title": "Microdrama Emerges as Mainstream Entertainment Format in India, Report Finds", "summary": "A report by ShareChat and Moj, in collaboration with Kantar, has identified microdrama as a mainstream entertainment format in India. The study highlights the growing popularity and acceptance of this short-form video content. The findings indicate a significant shift in audience consumption habits towards easily digestible and engaging digital content. This trend suggests a maturing digital entertainment landscape in the country.", "summary_points": ["Microdrama has become a mainstream entertainment format in India.", "The finding is based on a report by ShareChat and Moj, in collaboration with Kantar.", "The report highlights the growing popularity of short-form video content.", "This indicates a shift in audience consumption towards easily digestible digital content."], "title_hi": "शेयरचैट और मोज की रिपोर्ट: माइक्रोड्रामा भारत में मुख्यधारा का मनोरंजन प्रारूप बनकर उभरा", "summary_hi": "शेयरचैट और मोज की केंटार के सहयोग से जारी एक रिपोर्ट में माइक्रोड्रामा को भारत में एक मुख्यधारा के मनोरंजन प्रारूप के रूप में पहचाना गया है। अध्ययन इस छोटे प्रारूप वाले वीडियो सामग्री की बढ़ती लोकप्रियता और स्वीकृति पर प्रकाश डालता है। निष्कर्ष दर्शकों की उपभोग की आदतों में आसानी से पचने योग्य और आकर्षक डिजिटल सामग्री की ओर एक महत्वपूर्ण बदलाव का संकेत देते हैं। यह प्रवृत्ति देश में डिजिटल मनोरंजन परिदृश्य के परिपक्व होने का सुझाव देती है।", "summary_points_hi": ["माइक्रोड्रामा भारत में एक मुख्यधारा का मनोरंजन प्रारूप बन गया है।", "यह निष्कर्ष केंटार के सहयोग से शेयरचैट और मोज की रिपोर्ट पर आधारित है।", "रिपोर्ट छोटे प्रारूप वाले वीडियो सामग्री की बढ़ती लोकप्रियता पर प्रकाश डालती है।", "यह आसानी से पचने योग्य डिजिटल सामग्री की ओर दर्शकों की उपभोग की आदतों में बदलाव का संकेत देता है।"], "framing": {}, "framing_hi": {}, "topic": "Entertainment", "region": "India", "published_at": null, "image_url": "https://th-i.thgim.com/public/incoming/kfyuii/article71359855.ece/alternates/LANDSCAPE_1200/Screenshot%202026-08-18%20151547.png", "sources": [{"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "ShareChat and Mojs Report in Collaboration with Kantar Finds Microdrama has Emerged as a Mainstream Entertainment Format in India"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/sharechat-and-mojs-report-in-collaboration-with-kantar-finds-microdrama-has-emerged-as-a-mainstream-entertainment-format-in-india/article71359860.ece", "headline": "ShareChat and Moj’s Report in Collaboration with Kantar Finds Microdrama has Emerged as a Mainstream Entertainment Format in India"}], "coverage": {"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://th-i.thgim.com/public/incoming/kfyuii/article71359855.ece/alternates/LANDSCAPE_1200/Screenshot%202026-08-18%20151547.png', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.896800'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15947, 'Zeeba Appoints Chef Vikas Khanna as Global Brand Ambassador, Revamps Packaging', 'ज़ीबा ने शेफ विकास खन्ना को ग्लोबल ब्रांड एंबेसडर नियुक्त किया, पैकेजिंग में बदलाव', 'Food brand Zeeba has announced a significant rebranding initiative, including a revamp of its packaging. As part of this strategy, the company has appointed renowned Chef Vikas Khanna as its Global Brand Ambassador. This move aims to enhance Zeeba''s market presence and brand recognition.', 'खाद्य ब्रांड ज़ीबा ने अपनी पैकेजिंग में बदलाव सहित एक महत्वपूर्ण रीब्रांडिंग पहल की घोषणा की है। इस रणनीति के हिस्से के रूप में, कंपनी ने प्रसिद्ध शेफ विकास खन्ना को अपना ग्लोबल ब्रांड एंबेसडर नियुक्त किया है। इस कदम का उद्देश्य ज़ीबा की बाजार उपस्थिति और ब्रांड पहचान को बढ़ाना है।', '["Zeeba has revamped its packaging.", "Chef Vikas Khanna has been appointed as Zeeba''s Global Brand Ambassador.", "The appointment is part of Zeeba''s rebranding strategy.", "The company aims to improve its market presence with this initiative."]'::jsonb, '["ज़ीबा ने अपनी पैकेजिंग में बदलाव किया है।", "शेफ विकास खन्ना को ज़ीबा का ग्लोबल ब्रांड एंबेसडर नियुक्त किया गया है।", "यह नियुक्ति ज़ीबा की रीब्रांडिंग रणनीति का हिस्सा है।", "कंपनी का लक्ष्य इस पहल से अपनी बाजार उपस्थिति में सुधार करना है।"]'::jsonb, 'Society', 'India', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Zeeba Revamps Packaging and Announces Chef Vikas Khanna as Its Global Brand Ambassador"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/zeeba-revamps-packaging-and-announces-chef-vikas-khanna-as-its-global-brand-ambassador/article71359787.ece", "headline": "Zeeba Revamps Packaging and Announces Chef Vikas Khanna as Its Global Brand Ambassador"}]'::jsonb, '{"title": "Zeeba Appoints Chef Vikas Khanna as Global Brand Ambassador, Revamps Packaging", "summary": "Food brand Zeeba has announced a significant rebranding initiative, including a revamp of its packaging. As part of this strategy, the company has appointed renowned Chef Vikas Khanna as its Global Brand Ambassador. This move aims to enhance Zeeba''s market presence and brand recognition.", "summary_points": ["Zeeba has revamped its packaging.", "Chef Vikas Khanna has been appointed as Zeeba''s Global Brand Ambassador.", "The appointment is part of Zeeba''s rebranding strategy.", "The company aims to improve its market presence with this initiative."], "title_hi": "ज़ीबा ने शेफ विकास खन्ना को ग्लोबल ब्रांड एंबेसडर नियुक्त किया, पैकेजिंग में बदलाव", "summary_hi": "खाद्य ब्रांड ज़ीबा ने अपनी पैकेजिंग में बदलाव सहित एक महत्वपूर्ण रीब्रांडिंग पहल की घोषणा की है। इस रणनीति के हिस्से के रूप में, कंपनी ने प्रसिद्ध शेफ विकास खन्ना को अपना ग्लोबल ब्रांड एंबेसडर नियुक्त किया है। इस कदम का उद्देश्य ज़ीबा की बाजार उपस्थिति और ब्रांड पहचान को बढ़ाना है।", "summary_points_hi": ["ज़ीबा ने अपनी पैकेजिंग में बदलाव किया है।", "शेफ विकास खन्ना को ज़ीबा का ग्लोबल ब्रांड एंबेसडर नियुक्त किया गया है।", "यह नियुक्ति ज़ीबा की रीब्रांडिंग रणनीति का हिस्सा है।", "कंपनी का लक्ष्य इस पहल से अपनी बाजार उपस्थिति में सुधार करना है।"], "framing": {}, "framing_hi": {}, "topic": "Society", "region": "India", "published_at": null, "image_url": "https://th-i.thgim.com/public/incoming/8w0ruy/article71359808.ece/alternates/LANDSCAPE_1200/Ramneek%20Singh%20Chairman%20Supple%20Tek%20Industries%20Pvt.%20Ltd.%20%20Michelin-star%20Chef%20Vikas%20Khanna.jpg", "sources": [{"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Zeeba Revamps Packaging and Announces Chef Vikas Khanna as Its Global Brand Ambassador"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/zeeba-revamps-packaging-and-announces-chef-vikas-khanna-as-its-global-brand-ambassador/article71359787.ece", "headline": "Zeeba Revamps Packaging and Announces Chef Vikas Khanna as Its Global Brand Ambassador"}], "coverage": {"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://th-i.thgim.com/public/incoming/8w0ruy/article71359808.ece/alternates/LANDSCAPE_1200/Ramneek%20Singh%20Chairman%20Supple%20Tek%20Industries%20Pvt.%20Ltd.%20%20Michelin-star%20Chef%20Vikas%20Khanna.jpg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.873244'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.internatio