INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15946, 'Vehere Appoints Middle East Distributor', 'वेहेरे ने मध्य पूर्व वितरक नियुक्त किया', 'Vehere, a company specializing in communication and network security solutions, has appointed Avientek as its official distributor for the Middle East region. The announcement was made via a business wire release. Avientek will be responsible for distributing Vehere''s products across the Middle East. This partnership aims to expand Vehere''s market presence in the region.', 'संचार और नेटवर्क सुरक्षा समाधानों में विशेषज्ञता वाली कंपनी वेहेरे ने मध्य पूर्व क्षेत्र के लिए एविएंटेक को अपना आधिकारिक वितरक नियुक्त किया है। यह घोषणा एक बिजनेस वायर रिलीज के माध्यम से की गई थी। एविएंटेक मध्य पूर्व में वेहेरे के उत्पादों के वितरण के लिए जिम्मेदार होगा। इस साझेदारी का उद्देश्य क्षेत्र में वेहेरे की बाजार उपस्थिति का विस्तार करना है।', '["Vehere appointed Avientek as its official distributor for the Middle East.", "The announcement was made through a business wire release.", "Avientek will distribute Vehere''s communication and network security solutions.", "The partnership is intended to grow Vehere''s market reach in the Middle East."]'::jsonb, '["वेहेरे ने एविएंटेक को मध्य पूर्व के लिए अपना आधिकारिक वितरक नियुक्त किया है।", "यह घोषणा एक बिजनेस वायर रिलीज के माध्यम से की गई थी।", "एविएंटेक वेहेरे के संचार और नेटवर्क सुरक्षा समाधानों का वितरण करेगा।", "इस साझेदारी का उद्देश्य मध्य पूर्व में वेहेरे की बाजार पहुंच बढ़ाना है।"]'::jsonb, 'Society', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Print"], "owners": ["The Print"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Print", "owner": "The Print", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Vehere Appoints Avientek as Official Distributor for the Middle East"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/vehere-appoints-avientek-as-official-distributor-for-the-middle-east/article71359809.ece", "headline": "Vehere Appoints Avientek as Official Distributor for the Middle East"}]'::jsonb, '{"title": "Vehere Appoints Middle East Distributor", "summary": "Vehere, a company specializing in communication and network security solutions, has appointed Avientek as its official distributor for the Middle East region. The announcement was made via a business wire release. Avientek will be responsible for distributing Vehere''s products across the Middle East. This partnership aims to expand Vehere''s market presence in the region.", "summary_points": ["Vehere appointed Avientek as its official distributor for the Middle East.", "The announcement was made through a business wire release.", "Avientek will distribute Vehere''s communication and network security solutions.", "The partnership is intended to grow Vehere''s market reach in the Middle East."], "title_hi": "वेहेरे ने मध्य पूर्व वितरक नियुक्त किया", "summary_hi": "संचार और नेटवर्क सुरक्षा समाधानों में विशेषज्ञता वाली कंपनी वेहेरे ने मध्य पूर्व क्षेत्र के लिए एविएंटेक को अपना आधिकारिक वितरक नियुक्त किया है। यह घोषणा एक बिजनेस वायर रिलीज के माध्यम से की गई थी। एविएंटेक मध्य पूर्व में वेहेरे के उत्पादों के वितरण के लिए जिम्मेदार होगा। इस साझेदारी का उद्देश्य क्षेत्र में वेहेरे की बाजार उपस्थिति का विस्तार करना है।", "summary_points_hi": ["वेहेरे ने एविएंटेक को मध्य पूर्व के लिए अपना आधिकारिक वितरक नियुक्त किया है।", "यह घोषणा एक बिजनेस वायर रिलीज के माध्यम से की गई थी।", "एविएंटेक वेहेरे के संचार और नेटवर्क सुरक्षा समाधानों का वितरण करेगा।", "इस साझेदारी का उद्देश्य मध्य पूर्व में वेहेरे की बाजार पहुंच बढ़ाना है।"], "framing": {}, "framing_hi": {}, "topic": "Society", "region": "World", "published_at": null, "image_url": "https://th-i.thgim.com/public/incoming/vfpxdd/article71359824.ece/alternates/LANDSCAPE_1200/high.jpg", "sources": [{"source": "The Print", "owner": "The Print", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Vehere Appoints Avientek as Official Distributor for the Middle East"}, {"source": "The Hindu", "owner": "The Hindu Group", "lean": "left", "language": "en", "url": "https://www.thehindu.com/brandhub/pr-release/vehere-appoints-avientek-as-official-distributor-for-the-middle-east/article71359809.ece", "headline": "Vehere Appoints Avientek as Official Distributor for the Middle East"}], "coverage": {"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Print"], "owners": ["The Print"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://th-i.thgim.com/public/incoming/vfpxdd/article71359824.ece/alternates/LANDSCAPE_1200/high.jpg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.848487'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15945, 'Foreigners establish careers and homes in Taizhou', 'विदेशियों ने ताइझोउ में करियर और घर स्थापित किए', 'Foreign nationals have successfully established careers and found homes in the city of Taizhou. The coverage indicates that these individuals are building lives and professional paths within the city. Specific details regarding the number of foreigners, their professions, or the duration of their stay were not provided in the coverage.', 'विदेशी नागरिक ताइझोउ शहर में सफलतापूर्वक करियर स्थापित करने और घर खोजने में कामयाब रहे हैं। कवरेज से पता चलता है कि ये व्यक्ति शहर के भीतर जीवन और पेशेवर रास्ते बना रहे हैं। विदेशियों की संख्या, उनके पेशे या उनके रहने की अवधि के संबंध में विशिष्ट विवरण कवरेज में प्रदान नहीं किए गए थे।', '["Foreign nationals are establishing careers in Taizhou.", "Foreigners are finding homes and building lives in Taizhou.", "The coverage does not specify the number of foreigners or their professions."]'::jsonb, '["विदेशी नागरिक ताइझोउ में करियर स्थापित कर रहे हैं।", "विदेशियों को ताइझोउ में घर मिल रहे हैं और वे जीवन बना रहे हैं।", "कवरेज में विदेशियों की संख्या या उनके व्यवसायों का उल्लेख नहीं है।"]'::jsonb, 'Society', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Hindu"], "owners": ["The Hindu Group"]}, "center": {"count": 1, "sources": ["The Hindu BusinessLine"], "owners": ["The Hindu Group"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Hin