INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15944, 'FDA Notices Issued Over Vimal Elaichi Advertisement', 'विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस', 'Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.', 'महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।', '["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."]'::jsonb, '["महाराष्ट्र FDA ने शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए।", "नोटिस विमल इलायची के विज्ञापन से संबंधित हैं।", "FDA ने अभिनेताओं को चेतावनी जारी की है।", "अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया और माफी की मांग की।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["The Indian Express"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Punjab Kesari"], "owners": ["Punjab Kesari"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Punjab Kesari", "owner": "Punjab Kesari", "lean": "right", "language": "hi", "url": "https://www.punjabkesari.in/national/news/maharashtra-fda-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-elaichi-2369931", "headline": "शाहरुख - अजय - टाइगर की बढ़ी मुश्किलें , विमल इलायची विज्ञापन पर महाराष्ट्र FDA का नोटिस , जारी की चेतावनी - maharashtra fda shah rukh khan ajay devgn tiger shroff vimal elaichi"}, {"source": "The Indian Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://indianexpress.com/article/entertainment/bollywood/mukesh-khanna-fda-notices-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-ad-apologise-10838375", "headline": "Mukesh Khanna backs FDA notices to Shah Rukh, Ajay, Tiger over Vimal ad: ‘Apologise’"}]'::jsonb, '{"title": "FDA Notices Issued Over Vimal Elaichi Advertisement", "summary": "Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.", "summary_points": ["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."], "title_hi": "विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस", "summary_hi": "महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।", "summary_points_hi": ["महाराष्ट्र FDA ने शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए।", "नोटिस विमल इलायची के विज्ञापन से संबंधित हैं।", "FDA ने अभिनेताओं को चेतावनी जारी की है।", "अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया और माफी की मांग की।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "https://img.punjabkesari.in/multimedia/914/0/0X0/0/static.punjabkesari.in/2026_8image_10_19_195030100vimalelaichi.jpg", "sources": [{"source": "Punjab Kesari", "owner": "Punjab Kesari", "lean": "right", "language": "hi", "url": "https://www.punjabkesari.in/national/news/maharashtra-fda-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-elaichi-2369931", "headline": "शाहरुख - अजय - टाइगर की बढ़ी मुश्किलें , विमल इलायची विज्ञापन पर महाराष्ट्र FDA का नोटिस , जारी की चेतावनी - maharashtra fda shah rukh khan ajay devgn tiger shroff vimal elaichi"}, {"source": "The Indian Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://indianexpress.com/article/entertainment/bollywood/mukesh-khanna-fda-notices-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-ad-apologise-10838375", "headline": "Mukesh Khanna backs FDA notices to Shah Rukh, Ajay, Tiger over Vimal ad: ‘Apologise’"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["The Indian Express"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Punjab Kesari"], "owners": ["Punjab Kesari"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://img.punjabkesari.in/multimedia/914/0/0X0/0/static.punjabkesari.in/2026_8image_10_19_195030100vimalelaichi.jpg', FALSE, FALSE, 'llm', 'sl-14913', NULL, '2026-08-18T10:30:17.802783'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15943, 'Young professional quits high-paying job for fashion tech startup', 'युवती ने फैशन-टेक स्टार्टअप के लिए छोड़ी मोटी तनख्वाह वाली नौकरी', 'A 23-year-old woman resigned from her position at Morgan Stanley after four months, citing a desire for a different life path. She has chosen to pursue her ambition of starting a fashion-tech company. The decision was reportedly influenced by a desire to avoid a specific lifestyle and was aided by a cold email strategy. She was earning approximately ₹94 lakh annually.', '23 वर्षीय एक महिला ने एक अलग जीवन पथ की इच्छा का हवाला देते हुए चार महीने बाद मॉर्गन स्टेनली में अपने पद से इस्तीफा दे दिया। उसने फैशन-टेक कंपनी शुरू करने की अपनी महत्वाकांक्षा को पूरा करने का विकल्प चुना है। यह निर्णय कथित तौर पर एक विशिष्ट जीवन शैली से बचने की इच्छा से प्रभावित था और कोल्ड ईमेल रणनीति द्वारा सहायता प्राप्त की गई थी। वह सालाना लगभग ₹94 लाख कमा रही थी।', '["A 23-year-old individual resigned from Morgan Stanley after four months.", "The individual cited a desire for a different life and to avoid a particular lifestyle.", "The former employee plans to start a fashion-tech startup.", "A cold email strategy reportedly assisted in her new venture.", "Her previous annual salary was approximately ₹94 lakh."]'::jsonb, '["23 वर्षीय एक व्यक्ति ने चार महीने बाद मॉर्गन स्टेनली से इस्तीफा दे दिया।", "व्यक्ति ने एक अलग जीवन की इच्छा और एक विशेष जीवन शैली से बचने की इच्छा का हवाला दिया।", "पूर्व कर्मचारी एक फैशन-टेक स्टार्टअप शुरू करने की योजना बना रही है।", "कथित तौर पर एक कोल्ड ईमेल रणनीति ने उसके नए उद्यम में सहायता की।", "उसका पिछला वार्षिक वेतन लगभग ₹94 लाख था।"]'::jsonb, 'Society', 'India', 0, 1, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Hindustan Times", "Mint"], "owners": ["HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Hindustan Times", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "‘I didn’t want that life’: 23-year-old quits ₹94 lakh Morgan Stanley job after 4 months for fashion tech | Trending"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/us-news/23yearold-quits-morgan-stanley-to-start-fashion-tech-startup-reveals-how-cold-email-strategy-helped-her-11787045669047.html", "headline": "23-year-old quits Morgan Stanley to start fashion-tech startup, reveals how cold email strategy helped her"}]'::jsonb, '{"title": "Young professional quits high-paying job for fashion tech startup", "summary": "A 23-year-old woman resigned from her position at Morgan Stanley after four months, citing a desire for a different life path. She has chosen to pursue her ambition of starting a fashion-tech company. The decision was reportedly influenced by a desire to avoid a specific lifestyle and was aided by a cold email strategy. She was earning approximately ₹94 lakh annually.", "summary_points": ["A 23-year-old individual resigned from Morgan Stanley after four months.", "The individual cited a desire for a different life and to avoid a particular lifestyle.", "The former employee plans to start a fashion-tech startup.", "A cold email strategy reportedly assisted in her new venture.", "Her previous annual salary was approximately ₹94 lakh."], "title_hi": "युवती ने फैशन-टेक स्टार्टअप के लिए छोड़ी मोटी तनख्वाह वाली नौकरी", "summary_hi": "23 वर्षीय एक महिला ने एक अलग जीवन पथ की इच्छा का हवाला देते हुए चार महीने बाद मॉर्गन स्टेनली में अपने पद से इस्तीफा दे दिया। उसने फैशन-टेक कंपनी शुरू करने की अपनी महत्वाकांक्षा को पूरा करने का विकल्प चुना है। यह निर्णय कथित तौर पर एक विशिष्ट जीवन शैली से बचने की इच्छा से प्रभावित था और कोल्ड ईमेल रणनीति द्वारा सहायता प्राप्त की गई थी। वह सालाना लगभग ₹94 लाख कमा रही थी।", "summary_points_hi": ["23 वर्षीय एक व्यक्ति ने चार महीने बाद मॉर्गन स्टेनली से इस्तीफा दे दिया।", "व्यक्ति ने एक अलग जीवन की इच्छा और एक विशेष जीवन शैली से बचने की इच्छा का हवाला दिया।", "पूर्व कर्मचारी एक फैशन-टेक स्टार्टअप शुरू करने की योजना बना रही है।", "कथित तौर पर एक कोल्ड ईमेल रणनीति ने उसके नए उद्यम में सहायता की।", "उसका पिछला वार्षिक वेतन लगभग ₹94 लाख था।"], "framing": {}, "framing_hi": {}, "topic": "Society", "region": "India", "published_at": null, "image_url": "https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/pexels-photo-7429474_1787045779156_1787045801259_0f2e75bb-da47-4708-a198-e4895f918373.jpeg", "sources": [{"source": "Hindustan Times", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "‘I didn’t want that life’: 23-year-old quits ₹94 lakh Morgan Stanley job after 4 months for fashion tech | Trending"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/us-news/23yearold-quits-morgan-stanley-to-start-fashion-tech-startup-reveals-how-cold-email-strategy-helped-her-11787045669047.html", "headline": "23-year-old quits Morgan Stanley to start fashion-tech startup, reveals how cold email strategy helped her"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Hindustan Times", "Mint"], "owners": ["HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://www